class Task:
    def __init__(self, C_k, D_k, T_k):
        self.C = C_k
        self.D = D_k
        self.T = T_k

def is_implicit_deadline(task):
    return task.D == task.T

def is_constrained_deadline(task):
    return task.D <= task.T

class Job:
    def __init__(self, task_k, arrival_time):
        self.task = task_k
        self.arrival_time = arrival_time
        self.absolute_deadline = arrival_time + task_k.D
        self.finish_time = None

def calculate_carry_in(task_k, interval_start, interval_end, previous_jobs_state):
    # This is a conceptual sketch, actual calculation is complex
    carry_in_amount = 0
    for job in previous_jobs_state[task_k]:
        if job.arrival_time < interval_start and job.absolute_deadline > interval_start:
            # Estimate remaining execution time of this job at interval_start
            # and how much of it can execute within [interval_start, interval_end]
            carry_in_amount += min(job.remaining_execution_at_start, interval_end - interval_start)
    return carry_in_amount

def calculate_load(task_k, interval_start, interval_end, job_arrivals, previous_jobs_state):
    workload = calculate_workload(task_k, interval_start, interval_end, job_arrivals, previous_jobs_state)
    interval_length = interval_end - interval_start
    if interval_length <= 0:
        return 0 # Or handle error
    return workload / interval_length

def calculate_total_interference_from_individuals(tau_k, interval_start, interval_end, task_set, m, schedule_trace):
    total_individual_interference = 0
    for tau_i in task_set:
        total_individual_interference += calculate_individual_interference(tau_i, tau_k, interval_start, interval_end, schedule_trace)
    return total_individual_interference / m

class UniformMultiprocessor:
    def __init__(self, processor_speeds):
        self.m = len(processor_speeds)
        self.processor_speeds = processor_speeds
        self.S_pi = sum(processor_speeds)
        self.s_pi = max(processor_speeds)

def calculate_beta_i_BAK(tau_i, tau_k):
    U_i = calculate_utilization(tau_i)
    lambda_k = calculate_lambda(tau_k)
    term1 = U_i * (1 + (tau_i.T - tau_i.D) / tau_k.D)
    if lambda_k >= U_i:
        return term1
    else:
        term2 = (tau_i.C - lambda_k * tau_i.T) / tau_k.D
        return term1 + term2

def check_lemma4_equivalence(tau_k, a, b, x, task_set, m, schedule_trace):
    lhs = calculate_total_interference_from_individuals(tau_k, a, b, task_set, m, schedule_trace)
    rhs_sum = 0
    for tau_i in task_set:
        rhs_sum += min(calculate_individual_interference(tau_i, tau_k, a, b, schedule_trace), x)
    return (lhs >= x) == (rhs_sum >= m * x)

def bound_carry_in(tau_i, tau_k):
    N_i_jobs = calculate_N_i_jobs(tau_k.D, tau_i.T)
    remaining_time_after_full_jobs = tau_k.D - N_i_jobs * tau_i.T
    return min(tau_i.C, non_negative(remaining_time_after_full_jobs))

def check_theorem2_schedulability(S_pi, s_pi, m):
    if s_pi >= 1.0:
        return False # Condition s_pi < 1 must hold
    return S_pi <= m * (1 - s_pi) + s_pi

def bak_test(task_set, m):
    for tau_k in task_set:
        sum_beta_min = 0.0
        for tau_i in task_set:
            beta_i_BAK = calculate_beta_i_BAK(tau_i, tau_k)
            sum_beta_min += min(1.0, beta_i_BAK)

        lambda_k = calculate_lambda(tau_k)
        if lambda_k >= 1.0:
            # If lambda_k is 1 or more, the formula's (1-lambda_k) term becomes problematic.
            # This test is typically for lambda_k < 1.
            return False

        bound = m * (1 - lambda_k) + lambda_k
        if sum_beta_min > bound:
            return False # Task tau_k is not schedulable
    return True # All tasks are schedulable

def check_theorem6_schedulability(task_k, task_set, m, get_I_i_k_worst_case_func):
    slack_k = task_k.D - task_k.C
    if slack_k < 0: return False # Task cannot even execute its own C_k within D_k

    sum_min_interference = 0.0
    exists_active_interferer = False

    for tau_i in task_set:
        if tau_i == task_k: continue

        # In practice, get_I_i_k_worst_case_func would be an upper bound
        I_i_k_wc = get_I_i_k_worst_case_func(tau_i, task_k) 
        sum_min_interference += min(I_i_k_wc, slack_k)

        if 0 < I_i_k_wc <= slack_k:
            exists_active_interferer = True

    if sum_min_interference < m * slack_k:
        return True
    elif sum_min_interference == m * slack_k and exists_active_interferer:
        return True
    else:
        return False

def bcl_test(task_set, m):
    for tau_k in task_set:
        lambda_k = calculate_lambda(tau_k)
        if lambda_k >= 1.0: return False # Task cannot meet its own deadline

        slack_ratio_k = 1.0 - lambda_k
        sum_min_beta = 0.0
        exists_active_interferer = False

        for tau_i in task_set:
            if tau_i == tau_k: continue

            beta_i_BCL = calculate_beta_i_BCL(tau_i, tau_k)
            sum_min_beta += min(beta_i_BCL, slack_ratio_k)

            if 0 < beta_i_BCL <= slack_ratio_k:
                exists_active_interferer = True

        if sum_min_beta < m * slack_ratio_k:
            continue # tau_k is schedulable
        elif sum_min_beta == m * slack_ratio_k and exists_active_interferer:
            continue # tau_k is schedulable
        else:
            return False # tau_k is not schedulable
    return True # All tasks are schedulable

def calculate_beta_i_implicit(tau_i, tau_k):
    U_i = calculate_utilization(tau_i)
    U_k = calculate_utilization(tau_k)
    if U_k >= U_i:
        return U_i
    else:
        return U_i + (tau_i.C - U_k * tau_i.T) / tau_k.T # Note: T_k is used here for normalization

def corrected_simplified_bak_implicit(task_set, m):
    for tau_k in task_set:
        # Assuming implicit deadline, so D_k = T_k, lambda_k = U_k
        U_k = calculate_utilization(tau_k)
        if U_k >= 1.0: return False

        sum_beta_implicit = 0.0
        for tau_i in task_set:
            sum_beta_implicit += min(1.0, calculate_beta_i_implicit(tau_i, tau_k))

        bound = m * (1 - U_k) + U_k
        if sum_beta_implicit > bound:
            return False
    return True
